import contextlib
import io
import sys
import unittest
from unittest import mock

from textkit.cli import main
from textkit.slug import slugify


def run(argv, stdin=""):
    out, err = io.StringIO(), io.StringIO()
    with mock.patch.object(sys, "stdin", io.StringIO(stdin)), \
            contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
        code = main(argv)
    return code, out.getvalue(), err.getvalue()


class SlugifyFunctionTest(unittest.TestCase):
    def test_spec_examples(self):
        self.assertEqual(slugify("Héllo, Wörld!"), "hello-world")
        self.assertEqual(slugify("  C++ & Rust  "), "c-rust")
        self.assertEqual(slugify("a b", sep="_"), "a_b")

    def test_accents_are_folded(self):
        self.assertEqual(slugify("é"), "e")
        self.assertEqual(slugify("Crème Brûlée"), "creme-brulee")

    def test_non_ascii_without_fold_is_dropped(self):
        self.assertEqual(slugify("日本 tea"), "tea")

    def test_lower_cases(self):
        self.assertEqual(slugify("ABC Def"), "abc-def")

    def test_runs_of_separators_collapse(self):
        self.assertEqual(slugify("a   b---c!!d"), "a-b-c-d")

    def test_no_leading_or_trailing_sep(self):
        self.assertEqual(slugify("--hi there--"), "hi-there")

    def test_digits_are_kept(self):
        self.assertEqual(slugify("Release 2.0 now"), "release-2-0-now")

    def test_custom_sep(self):
        self.assertEqual(slugify("a b  c", sep="_"), "a_b_c")

    def test_empty_sep_joins_words(self):
        self.assertEqual(slugify("a b", sep=""), "ab")

    def test_nothing_left_raises(self):
        for text in ["!!!", "", "   ", "日本語", "---"]:
            with self.subTest(text=text):
                with self.assertRaises(ValueError):
                    slugify(text)


class SlugCommandTest(unittest.TestCase):
    def test_example(self):
        code, out, err = run(["slug", "Héllo, Wörld!"])
        self.assertEqual((code, out, err), (0, "hello-world\n", ""))

    def test_sep_option(self):
        code, out, _ = run(["slug", "a b", "--sep", "_"])
        self.assertEqual((code, out), (0, "a_b\n"))

    def test_nothing_left_is_an_error(self):
        code, out, err = run(["slug", "!!!"])
        self.assertEqual(code, 2)
        self.assertEqual(out, "")
        self.assertTrue(err.startswith("error: "), err)

    def test_json_output(self):
        code, out, _ = run(["--json", "slug", "A B"])
        self.assertEqual(code, 0)
        self.assertEqual(out, '{"command": "slug", "exit": 0, "output": ["a-b"]}\n')

    def test_listed_in_commands(self):
        _, out, _ = run(["commands"])
        self.assertIn("slug\n", out)


if __name__ == "__main__":
    unittest.main()
