         [("text", {}), ("--n", {"default": 13})])
def _rot(a):
    # argparse leaves --n as a string when given on the command line, so convert here.
    try:
        n = int(a.n)
    except (TypeError, ValueError):
        raise ValueError(f"n must be an integer, not {a.n!r}")
    print(rot(a.text, n))
    return 0


