from unittest import mock

from textkit.cli import main
from textkit.topwords import top_words


def run(argv, stdin=""):
    out, err = io.StringIO(), io.StringIO()
    with mock.patch.object(sys, "stdin", io.StringIO(stdin)), \
            contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
        code = main(argv)
    return code, out.getvalue(), err.getvalue()


class TopWordsFunctionTest(unittest.TestCase):
    def test_spec_example(self):
        self.assertEqual(top_words("b a b c a b", 2), [("b", 3), ("a", 2)])

    def test_counts_case_insensitively(self):
        self.assertEqual(top_words("The the THE cat", 1), [("the", 3)])

    def test_splits_on_non_letters(self):
        self.assertEqual(top_words("don't", 5), [("don", 1), ("t", 1)])
        self.assertEqual(top_words("a1b2-a3", 5), [("a", 2), ("b", 1)])

    def test_ties_break_alphabetically(self):
        self.assertEqual(top_words("zebra apple mango", 3),
                         [("apple", 1), ("mango", 1), ("zebra", 1)])

    def test_count_beats_alphabetical_order(self):
        self.assertEqual(top_words("z z z a a b", 3), [("z", 3), ("a", 2), ("b", 1)])

    def test_fewer_words_than_k_returns_all(self):
        self.assertEqual(top_words("hi hi", 10), [("hi", 2)])

    def test_empty_text_returns_empty_list(self):
        self.assertEqual(top_words("", 3), [])
        self.assertEqual(top_words("123 !!!", 3), [])

    def test_k_below_one_raises(self):
        for k in [0, -1]:
            with self.subTest(k=k):
                with self.assertRaises(ValueError):
                    top_words("a b", k)


