        code, out, err = run(["top", "x", "--k", "0"])
        self.assertEqual(code, 2)
        self.assertEqual(out, "")
        self.assertTrue(err.startswith("error: "), err)

    def test_non_integer_k_is_an_error(self):
        code, out, err = run(["top", "x", "--k", "many"])
        self.assertEqual(code, 2)
        self.assertEqual(out, "")
        self.assertTrue(err.startswith("error: "), err)

    def test_json_output(self):
        code, out, _ = run(["--json", "top", "a a b", "--k", "2"])
        self.assertEqual(code, 0)
        self.assertEqual(out, '{"command": "top", "exit": 0, "output": ["a 2", "b 1"]}\n')

